 const role=sessionStorage.getItem('aa-role')||'owner',isMechanic=['gavin','auris','mohammad','jack'].includes(role),canEditSettings=role==='owner'||!!readEmployeePermissions()[role]?.garageSettingsEdit,initial:Workspace=role==='sandra'?'front':role==='driver'||isMechanic?'technician':'manager',workspaceViewKey=`aa-garage-visible-workspaces-${role}`;
 const[visible,setVisible]=useState<Workspace[]>(()=>{if(isMechanic)return['technician'];if(customerSection)return['customers'];if(initialWorkspace)return[initialWorkspace];try{const saved=JSON.parse(localStorage.getItem(workspaceViewKey)||'null');return Array.isArray(saved)&&saved.some(item=>['customers','front','manager','technician'].includes(item))?saved:[initial]}catch{return[initial]}}),[jobs,setJobs]=useState<Job[]>(readJobs),[createdJobs,setCreatedJobs]=useState<Job[]>(readCreatedJobs),[query,setQuery]=useState(''),[selected,setSelected]=useState<Job|null>(null),[editing,setEditing]=useState(false),[editNotice,setEditNotice]=useState('');
