 useEffect(()=>{const refresh=(event:Event)=>{if(event instanceof StorageEvent&&event.key!==storageKey)return;const latest=readJobs();setJobs(latest);setSelected(current=>current?latest.find(job=>job.id===current.id)||null:current)};window.addEventListener('storage',refresh);window.addEventListener('aa-garage-jobs-updated',refresh);return()=>{window.removeEventListener('storage',refresh);window.removeEventListener('aa-garage-jobs-updated',refresh)}},[]);
 useEffect(()=>{const refresh=()=>setCreatedJobs(readCreatedJobs());window.addEventListener('storage',refresh);window.addEventListener('aa-garage-job-cards-updated',refresh);return()=>{window.removeEventListener('storage',refresh);window.removeEventListener('aa-garage-job-cards-updated',refresh)}},[]);
